"use client";

import { useLayoutEffect, type ReactNode } from "react";
import { ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { EditorPreview } from "@/components/ui/editor-preview";
import { useLineSync, STREAK_PAD, type UseLineSyncReturn } from "@/hooks/use-line-sync";

/**
 * Size presets — each sets height AND width (width clamped to the container).
 * `screen` matches justin06lee.dev/desk: full container width, viewport height
 * minus a header allowance. `auto` opts out so `className` owns the sizing.
 * Any preset can still be overridden by `h-*` / `w-*` classes in `className`.
 */
export type EditorSize = "sm" | "md" | "lg" | "xl" | "2xl" | "screen" | "auto";

export const EDITOR_SIZE_CLASS: Record<Exclude<EditorSize, "auto">, string> = {
  sm: "h-80 w-[32rem] max-w-full mx-auto",
  md: "h-[28rem] w-[44rem] max-w-full mx-auto",
  lg: "h-[36rem] w-[56rem] max-w-full mx-auto",
  xl: "h-[44rem] w-[72rem] max-w-full mx-auto",
  "2xl": "h-[52rem] w-[88rem] max-w-full mx-auto",
  screen: "h-[calc(100dvh-10rem)] min-h-[24rem] w-full",
};

export function editorSizeClass(size: EditorSize): string | undefined {
  return size === "auto" ? undefined : EDITOR_SIZE_CLASS[size];
}

export interface EditorTextareaProps {
  /** A `useLineSync(...)` return value, shared with the paired `<EditorPreview>`. */
  sync: UseLineSyncReturn;
  /** Markdown source (controlled). */
  value: string;
  /** Called with the next markdown source on edit. */
  onChange: (value: string) => void;
  placeholder?: string;
  /**
   * Passthrough `keydown` on the textarea. An escape hatch for layering your own
   * keymap (e.g. a vim mode) over the plain editor without forking it.
   */
  onKeyDown?: (event: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  /** Sizing/extra classes (give it a height). */
  className?: string;
}

/**
 * The editor half on its own: a `<textarea>` with the gray-streak + "preview"
 * button overlay, driven by a `useLineSync` engine. Pair it with a `<EditorPreview>`
 * that shares the same engine and they stay in sync even in separate, non-adjacent
 * containers — the engine aligns by viewport coordinates, not relative layout.
 */
export function EditorTextarea({
  sync,
  value,
  onChange,
  placeholder,
  onKeyDown,
  className,
}: EditorTextareaProps) {
  const {
    textareaRef,
    overlayLayerRef,
    editorScrollTopRef,
    syncedRect,
    selection,
    selectionRect,
    syncToPreview,
    refreshSelection,
    clearSelection,
    handleScroll,
  } = sync;

  // On mount, sync the overlay to the fresh textarea's scroll position — after
  // a remount (e.g. a desk mode toggle) the shared ref still holds the old
  // textarea's scrollTop, which would offset the overlay until the next scroll.
  useLayoutEffect(() => {
    handleScroll(textareaRef.current?.scrollTop ?? 0);
  }, [handleScroll, textareaRef]);

  return (
    <div className={cn("relative min-h-0 overflow-hidden", className)}>
      <div className="relative h-full min-h-0">
        {/* overlay layer: translated on scroll so streak/button track text 1:1 */}
        <div
          ref={overlayLayerRef}
          className="pointer-events-none absolute inset-0 z-10"
          style={{ transform: `translateY(${-editorScrollTopRef.current}px)` }}
        >
          {syncedRect != null ? (
            <div
              aria-hidden
              className="absolute left-0 right-0 bg-white/10"
              style={{ top: syncedRect.top - STREAK_PAD, height: syncedRect.height + STREAK_PAD * 2 }}
            />
          ) : null}
          {selection != null && selectionRect != null ? (
            <button
              type="button"
              // preventDefault keeps the textarea focused + its selection intact
              onMouseDown={(event) => event.preventDefault()}
              onClick={syncToPreview}
              className="pointer-events-auto absolute right-2 flex items-center gap-1 border border-white/20 bg-black px-2 py-1 text-xs text-white/80 shadow-lg transition-colors hover:bg-white/10 hover:text-white"
              style={{
                top: selectionRect.top,
                transform:
                  selectionRect.top - editorScrollTopRef.current > 28
                    ? "translateY(calc(-100% - 4px))"
                    : "translateY(4px)",
              }}
            >
              <ArrowRight size={12} aria-hidden />
              preview
            </button>
          ) : null}
        </div>
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onMouseUp={refreshSelection}
          onSelect={refreshSelection}
          onBlur={clearSelection}
          onKeyDown={onKeyDown}
          onScroll={(event) => handleScroll(event.currentTarget.scrollTop)}
          spellCheck={false}
          placeholder={placeholder}
          className="h-full w-full resize-none bg-black px-4 py-6 font-mono text-[13px] leading-6 text-white/90 outline-none placeholder:text-white/30 lg:px-8"
        />
      </div>
    </div>
  );
}

export interface EditorProps {
  /** Markdown source (controlled). */
  value: string;
  /** Called with the next markdown source on edit. */
  onChange: (value: string) => void;
  /**
   * Renders the markdown with line-sync enabled — typically
   * `(md, { highlightLine }) => <Prose lineSync highlightLine={highlightLine}>{md}</Prose>`.
   */
  renderMarkdown: (
    markdown: string,
    state: { highlightLine: number | null },
  ) => ReactNode;
  /** Sticky label over the preview pane. Defaults to "live preview". */
  label?: ReactNode;
  /** Editor textarea placeholder. */
  placeholder?: string;
  /** Size preset (height + width); defaults to the container-filling `screen`. */
  size?: EditorSize;
  /** Extra classes for the root; `h-*` / `w-*` classes here override `size`. */
  className?: string;
}

/**
 * Turnkey split-pane markdown editor: `EditorTextarea` beside a
 * `<EditorPreview>`, sharing one `useLineSync` engine so the preview scrolls and
 * highlights in sync both ways. Dark-only. Sized via the `size` preset
 * (viewport-filling by default, like justin06lee.dev/desk). For a custom
 * layout, drop down to `useLineSync` + the two pieces directly.
 */
export function Editor({
  value,
  onChange,
  renderMarkdown,
  label = "live preview",
  placeholder,
  size = "screen",
  className,
}: EditorProps) {
  const sync = useLineSync({ value });

  return (
    <div className={cn("flex min-h-0 flex-col md:flex-row", editorSizeClass(size), className)}>
      <EditorTextarea
        sync={sync}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        className="flex-1 border-b border-white/10 md:border-b-0 md:border-r"
      />
      <EditorPreview
        ref={sync.previewRef}
        content={value}
        renderMarkdown={renderMarkdown}
        onSelectBlock={sync.onPreviewSelectBlock}
        label={label}
        className="min-h-0 flex-1"
      />
    </div>
  );
}

"use client";

import {
  forwardRef,
  memo,
  useImperativeHandle,
  useRef,
  useState,
  type MouseEvent,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";

export interface PreviewBlockSelection {
  /** 1-based source line where the clicked block starts. */
  startLine: number;
  /**
   * 1-based source line where the next block starts (exclusive end), or null
   * when the clicked block is the last one.
   */
  endLine: number | null;
  /**
   * Viewport y (px) of the clicked block's top edge, so an editor can scroll its
   * matching text to the same height.
   */
  screenY: number;
  /**
   * Rendered height (px) of the clicked block, so an editor can center its
   * (shorter, denser mono) matching text against this block instead of just
   * aligning top edges — otherwise the two highlights look vertically offset.
   */
  screenHeight: number;
}

export interface EditorPreviewHandle {
  /**
   * Scroll the block for a 1-based source line so its top edge lands at
   * `screenY` (a viewport coordinate), putting it level with the editor
   * selection it was triggered from, then highlight it.
   */
  alignLineToScreenY: (line: number, screenY: number) => void;
}

export interface EditorPreviewProps {
  /** Markdown source rendered through `renderMarkdown`. */
  content: string;
  /**
   * Renders the markdown with line-sync enabled and the current highlight line
   * applied — typically `(md, { highlightLine }) =>
   * <Prose lineSync highlightLine={highlightLine}>{md}</Prose>`. The renderer
   * MUST stamp `data-source-line` on top-level blocks (and `data-sync-highlight`
   * on the highlighted one) for sync to work.
   */
  renderMarkdown: (
    markdown: string,
    state: { highlightLine: number | null },
  ) => ReactNode;
  /** Fired when the user clicks a block in the preview. */
  onSelectBlock?: (selection: PreviewBlockSelection) => void;
  /** Optional sticky label shown over the top of the scroll area. */
  label?: ReactNode;
  className?: string;
}

// memo so unrelated editor state changes (e.g. clearing a text selection on
// blur) don't re-run the markdown renderer here. Each such re-render briefly
// reflows the preview, shifting a block out from under the pointer mid-click so
// the click is lost. Requires onSelectBlock to be a stable (useCallback) ref.
export const EditorPreview = memo(
  forwardRef<EditorPreviewHandle, EditorPreviewProps>(function EditorPreview(
    { content, renderMarkdown, onSelectBlock, label = "live preview", className },
    ref,
  ) {
    const scrollRef = useRef<HTMLDivElement>(null);
    const headerRef = useRef<HTMLDivElement>(null);
    // The highlighted block is driven declaratively: we hold the 1-based source
    // line and hand it to the renderer, which stamps data-sync-highlight on the
    // matching block as it renders. An imperatively-toggled class would get wiped
    // when the renderer rebuilds its DOM on the next render; rendering it into the
    // markup survives that.
    const [highlightLine, setHighlightLine] = useState<number | null>(null);

    function sourceLineBlocks(): HTMLElement[] {
      const container = scrollRef.current;
      if (!container) return [];
      return Array.from(
        container.querySelectorAll<HTMLElement>("[data-source-line]"),
      );
    }

    // pick the last top-level block whose source line is <= the target line
    function findBlockForLine(line: number): HTMLElement | null {
      const blocks = sourceLineBlocks();
      if (blocks.length === 0) return null;
      let best: HTMLElement | null = null;
      for (const block of blocks) {
        const blockLine = Number(block.getAttribute("data-source-line"));
        if (blockLine <= line) {
          best = block;
        } else {
          break;
        }
      }
      return best ?? blocks[0] ?? null;
    }

    useImperativeHandle(ref, () => ({
      alignLineToScreenY(line: number, screenY: number) {
        const container = scrollRef.current;
        if (!container) return;
        const element = findBlockForLine(line);
        if (!element) return;
        // The label bar is sticky over the top of the scroll area, so a block
        // scrolled to a screenY inside that band lands hidden behind it. Clamp
        // the target to just below the bar so the block stays visible while still
        // sitting as close as possible to the editor selection's height.
        const containerTop = container.getBoundingClientRect().top;
        const headerBottom =
          containerTop + (headerRef.current?.offsetHeight ?? 0);
        const targetY = Math.max(screenY, headerBottom);
        // scroll the block to the target height; the browser clamps the scroll at
        // the content bounds, so near the very bottom the block lands as close as
        // it can. We do NOT move the other pane to compensate — the pane the user
        // is looking at should stay where they put it.
        const delta = element.getBoundingClientRect().top - targetY;
        container.scrollBy({ top: delta, behavior: "smooth" });
        setHighlightLine(line);
      },
    }));

    function handleSelectBlock(event: MouseEvent<HTMLDivElement>) {
      const target = (event.target as HTMLElement).closest<HTMLElement>(
        "[data-source-line]",
      );
      if (!target) return;
      const startLine = Number(target.getAttribute("data-source-line"));
      if (!Number.isFinite(startLine)) return;
      // endLine bounds the block: the next tagged block's line, so an editor can
      // highlight the whole paragraph/range. Compute it by source-line VALUE
      // (smallest line greater than startLine), not node identity.
      let endLine: number | null = null;
      for (const block of sourceLineBlocks()) {
        const line = Number(block.getAttribute("data-source-line"));
        if (Number.isFinite(line) && line > startLine) {
          endLine = line;
          break;
        }
      }
      setHighlightLine(startLine);
      if (!onSelectBlock) return;
      const targetRect = target.getBoundingClientRect();
      onSelectBlock({
        startLine,
        endLine,
        screenY: targetRect.top,
        screenHeight: targetRect.height,
      });
    }

    return (
      <div
        ref={scrollRef}
        onClick={handleSelectBlock}
        className={cn("min-h-0 overflow-y-auto bg-black", className)}
      >
        {label != null ? (
          <div
            ref={headerRef}
            className="sticky top-0 z-10 border-b border-white/10 bg-black px-4 py-3 text-xs font-medium text-white/70"
          >
            {label}
          </div>
        ) : null}
        <div className="px-4 py-6 lg:px-8">
          {renderMarkdown(content, { highlightLine })}
        </div>
      </div>
    );
  }),
);

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
} from "react";
import type {
  PreviewBlockSelection,
  EditorPreviewHandle,
} from "@/components/ui/editor-preview";

function clamp(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, n));
}

/** 1-based source line containing char `offset`. */
export function offsetToLine(text: string, offset: number): number {
  return text.slice(0, clamp(offset, 0, text.length)).split("\n").length;
}

/** Char offset where 1-based `line` begins (clamps past the end to text length). */
export function lineStartOffset(text: string, line: number): number {
  if (line <= 1) return 0;
  let seen = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === "\n") {
      seen += 1;
      if (seen === line - 1) return i + 1;
    }
  }
  return text.length;
}

/**
 * Char-offset range for a clicked preview block, given its 1-based `startLine`
 * and the next block's `startLine` as `endLine` (or null when it's the last
 * block). Trailing blank lines are trimmed so the streak covers only the block's
 * text — not the blank separator or the next block's fence/heading — and the end
 * sits before the final newline so the streak's bottom lands on the last text row.
 */
export function trimStreakRange(
  text: string,
  startLine: number,
  endLine: number | null,
): { start: number; end: number } {
  const start = lineStartOffset(text, startLine);
  const lines = text.split("\n");
  let lastLine = endLine == null ? lines.length : endLine - 1;
  while (lastLine > startLine && (lines[lastLine - 1] ?? "").trim() === "") {
    lastLine -= 1;
  }
  let end = lineStartOffset(text, lastLine + 1);
  if (end > start && text[end - 1] === "\n") end -= 1;
  return { start, end: Math.max(start, end) };
}

// --- pixel measurement (mirror-div technique) --------------------------------

export interface SelectionRect {
  /** pixels from the top of the textarea's content (caret coords, scroll-agnostic) */
  top: number;
  height: number;
}

/** vertical breathing room (px) added above/below the editor's gray streak */
export const STREAK_PAD = 3;

// computed-style props the mirror div must copy so its text wraps exactly like
// the textarea (same font metrics + wrapping rules => same line breaks)
const MIRROR_STYLE_PROPS = [
  "boxSizing",
  "paddingTop",
  "paddingRight",
  "paddingBottom",
  "paddingLeft",
  "fontFamily",
  "fontSize",
  "fontWeight",
  "fontStyle",
  "fontVariant",
  "letterSpacing",
  "lineHeight",
  "textTransform",
  "textIndent",
  "whiteSpace",
  "wordSpacing",
  "tabSize",
] as const;

// Build a hidden div that wraps text exactly like the textarea, then read the
// pixel top of the line containing `position`. Putting the *remaining* text in
// the measured span keeps the line breaks after `position` identical to the
// textarea. (The classic textarea-caret-position technique.)
function measureCaretTop(
  textarea: HTMLTextAreaElement,
  computed: CSSStyleDeclaration,
  position: number,
): number {
  const doc = textarea.ownerDocument;
  const div = doc.createElement("div");
  const style = div.style;
  for (const prop of MIRROR_STYLE_PROPS) {
    style[prop] = computed[prop];
  }
  style.position = "absolute";
  style.top = "-9999px";
  style.left = "-9999px";
  style.visibility = "hidden";
  style.overflow = "hidden";
  style.height = "auto";
  // clientWidth excludes any scrollbar, so wrapping matches what the user sees;
  // border-box + copied padding then reproduces the exact content width
  style.boxSizing = "border-box";
  style.width = `${textarea.clientWidth}px`;
  style.borderWidth = "0";

  const value = textarea.value;
  div.textContent = value.slice(0, position);
  const span = doc.createElement("span");
  // trailing "." so a position at the very end still produces a laid-out box
  span.textContent = value.slice(position) || ".";
  div.appendChild(span);

  doc.body.appendChild(div);
  // offsetTop is measured from the offsetParent's padding edge (inside the
  // border), so add the textarea's top border to land in its border-box space,
  // which is where the absolutely-positioned overlay/button live.
  const borderTop = parseFloat(computed.borderTopWidth) || 0;
  const top = span.offsetTop + borderTop;
  doc.body.removeChild(div);
  return top;
}

// A textarea can't report caret pixel coordinates, and its lines soft-wrap, so
// line-number * line-height is wrong. Measure the selection's start and end rows
// via the mirror div. Returns content-space coords; subtract scrollTop for the
// viewport position.
function measureSelectionRect(
  textarea: HTMLTextAreaElement,
  start: number,
  end: number,
): SelectionRect | null {
  const computed = window.getComputedStyle(textarea);
  const lineHeight = parseFloat(computed.lineHeight) || 24;
  const top = measureCaretTop(textarea, computed, start);
  const endTop = end > start ? measureCaretTop(textarea, computed, end) : top;
  return { top, height: Math.max(lineHeight, endTop + lineHeight - top) };
}

// --- the engine hook ---------------------------------------------------------

export interface UseLineSyncOptions {
  /** The markdown source being edited. */
  value: string;
}

export interface UseLineSyncReturn {
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  previewRef: RefObject<EditorPreviewHandle | null>;
  overlayLayerRef: RefObject<HTMLDivElement | null>;
  editorScrollTopRef: RefObject<number>;
  /** Pixel rect of the gray streak, or null. */
  syncedRect: SelectionRect | null;
  /** Live non-empty selection, or null (drives the floating sync button). */
  selection: { start: number; end: number } | null;
  /** Pixel rect of the selection (for placing the button), or null. */
  selectionRect: SelectionRect | null;
  /** Fire the editor-to-preview sync (call from the floating button). */
  syncToPreview: () => void;
  /** Handler for a preview block click (pass to EditorPreview's onSelectBlock). */
  onPreviewSelectBlock: (selection: PreviewBlockSelection) => void;
  /** Refresh the tracked selection (pass to the textarea's onSelect/onMouseUp). */
  refreshSelection: () => void;
  /** Clear the selection (pass to the textarea's onBlur). */
  clearSelection: () => void;
  /** Track the textarea's internal scroll so the overlay follows (onScroll). */
  handleScroll: (scrollTop: number) => void;
}

/**
 * Bidirectional editor ↔ preview sync engine. Owns the caret↔line math, the
 * pixel measurement, the overlay scroll-follow, and the two-way coordination.
 * Pair it with a `<textarea>` and a `<EditorPreview>` (see editor.tsx).
 */
export function useLineSync({ value }: UseLineSyncOptions): UseLineSyncReturn {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const previewRef = useRef<EditorPreviewHandle>(null);
  const overlayLayerRef = useRef<HTMLDivElement>(null);
  const editorScrollTopRef = useRef(0);

  // Live non-empty selection the floating sync button acts on. char offsets.
  const [selection, setSelection] = useState<{ start: number; end: number } | null>(null);
  // The synced range shown as a persistent gray streak (set on either sync).
  const [syncedRange, setSyncedRange] = useState<{ start: number; end: number } | null>(null);
  // Pixel rects measured via the mirror div; recomputed when range/text change,
  // not on every scroll frame. measureNonce lets a resize force a re-measure.
  const [selectionRect, setSelectionRect] = useState<SelectionRect | null>(null);
  const [syncedRect, setSyncedRect] = useState<SelectionRect | null>(null);
  const [measureNonce, setMeasureNonce] = useState(0);

  const handleScroll = useCallback((scrollTop: number) => {
    editorScrollTopRef.current = scrollTop;
    if (overlayLayerRef.current) {
      overlayLayerRef.current.style.transform = `translateY(${-scrollTop}px)`;
    }
  }, []);

  const refreshSelection = useCallback(() => {
    const textarea = textareaRef.current;
    if (!textarea) return;
    const { selectionStart, selectionEnd } = textarea;
    setSelection(selectionStart === selectionEnd ? null : { start: selectionStart, end: selectionEnd });
  }, []);

  const clearSelection = useCallback(() => setSelection(null), []);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (!textarea || !selection) {
      setSelectionRect(null);
      return;
    }
    setSelectionRect(measureSelectionRect(textarea, selection.start, selection.end));
  }, [selection, value, measureNonce]);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (!textarea || !syncedRange) {
      setSyncedRect(null);
      return;
    }
    setSyncedRect(measureSelectionRect(textarea, syncedRange.start, syncedRange.end));
  }, [syncedRange, value, measureNonce]);

  useEffect(() => {
    function onResize() {
      setMeasureNonce((n) => n + 1);
    }
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  // editor -> preview: scroll the matching preview block to the same viewport
  // height as the selection and leave a gray streak. The editor stays put.
  const syncToPreview = useCallback(() => {
    const textarea = textareaRef.current;
    if (!textarea || !selection) return;
    const rect = selectionRect ?? measureSelectionRect(textarea, selection.start, selection.end);
    if (!rect) return;
    const screenY = textarea.getBoundingClientRect().top + rect.top - textarea.scrollTop;
    // The editor text *is* the rendered source, so the editor line is the
    // content line directly (no title/metadata header offset to subtract).
    const line = offsetToLine(value, selection.start);
    previewRef.current?.alignLineToScreenY(line, screenY);
    setSyncedRange({ start: selection.start, end: selection.end });
    // swap the native selection for our gray streak; keep focus + caret
    textarea.setSelectionRange(selection.start, selection.start);
    setSelection(null);
  }, [selection, selectionRect, value]);

  // preview -> editor: scroll the editor so the matching text lands level with
  // the clicked block, and lay a gray streak over the block's lines.
  const onPreviewSelectBlock = useCallback(
    ({ startLine, endLine, screenY, screenHeight }: PreviewBlockSelection) => {
      const textarea = textareaRef.current;
      if (!textarea) return;
      const { start, end } = trimStreakRange(value, startLine, endLine);
      setSyncedRange({ start, end });
      const rect = measureSelectionRect(textarea, start, end);
      if (!rect) return;
      const taTop = textarea.getBoundingClientRect().top;
      // line the block's CENTER up with the clicked preview block's center (not
      // just top edges): the editor's mono text is denser than the preview's
      // prose, so equal blocks have different heights; centering keeps the two
      // highlights visually level.
      const aligned = rect.top - (screenY - taTop) + (rect.height - screenHeight) / 2;
      // but if that would push the block's last line below the editor, pull it up
      // so its bottom rests at the editor's bottom. Capped so the first line never
      // scrolls past the top.
      const endAtBottom = rect.top + rect.height - textarea.clientHeight;
      const target = Math.min(Math.max(aligned, endAtBottom), rect.top);
      textarea.scrollTo({ top: Math.max(0, target), behavior: "smooth" });
    },
    [value],
  );

  return {
    textareaRef,
    previewRef,
    overlayLayerRef,
    editorScrollTopRef,
    syncedRect,
    selection,
    selectionRect,
    syncToPreview,
    onPreviewSelectBlock,
    refreshSelection,
    clearSelection,
    handleScroll,
  };
}
